function validate([hours]) {
  if (!Array.isArray(hours) || hours.length < 1 || hours.length > 10000) return 'hours needs 1 to 10^4 days.';
  if (hours.some(h => !Number.isInteger(h) || h < 0 || h > 16)) return 'Each day is a whole number of hours from 0 to 16.';
  return null;
}

