function longestWPI(hours) {
  const firstSeen = new Map();
  let score = 0;
  let best = 0;
  for (let day = 0; day < hours.length; day++) {
    score += hours[day] > 8 ? 1 : -1;
    if (score > 0) {
      best = day + 1;
    } else if (firstSeen.has(score - 1)) {
      best = Math.max(best, day - firstSeen.get(score - 1));
    }
    if (!firstSeen.has(score)) {
      firstSeen.set(score, day);
    }
  }
  return best;
}

