function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 12);
  // The chance of a tiring day varies so that answers range from 0 to the whole array.
  const chance = size === 'large' ? 0.3 + rand() * 0.25 : rand();
  const hours = [];
  for (let i = 0; i < n; i++) {
    const tiring = rand() < chance;
    const r = rand();
    if (tiring) hours.push(r < 0.3 ? 9 : r < 0.4 ? 16 : 9 + Math.floor(rand() * 8));
    else hours.push(r < 0.3 ? 8 : r < 0.4 ? 0 : Math.floor(rand() * 9));
  }
  return [hours];
}
